IF DB_ID('AICompany') IS NULL CREATE DATABASE AICompany;
GO
USE AICompany;
GO

CREATE TABLE Company(CompanyID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), CompanyName nvarchar(200) NOT NULL, Status varchar(20) NOT NULL DEFAULT 'Active', CreatedAtUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Department(DepartmentID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), CompanyID uniqueidentifier NOT NULL REFERENCES Company(CompanyID), DepartmentName nvarchar(150) NOT NULL, Status varchar(20) NOT NULL DEFAULT 'Active', CreatedAtUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), CONSTRAINT UQ_Department UNIQUE(CompanyID,DepartmentName));
CREATE TABLE Position(PositionID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), DepartmentID uniqueidentifier NOT NULL REFERENCES Department(DepartmentID), PositionName nvarchar(150) NOT NULL, Grade varchar(20) NOT NULL, Status varchar(20) NOT NULL DEFAULT 'Active');
CREATE TABLE Skill(SkillID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), Name nvarchar(150) NOT NULL UNIQUE, Description nvarchar(1000), Version varchar(30) NOT NULL, InputSchema nvarchar(max), OutputSchema nvarchar(max), RequiredTools nvarchar(max), RequiredPermissions nvarchar(max), RiskLevel varchar(20) NOT NULL, Owner nvarchar(200) NOT NULL, Status varchar(20) NOT NULL);
CREATE TABLE Tool(ToolID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), ToolName nvarchar(150) NOT NULL UNIQUE, ToolType varchar(40) NOT NULL, Endpoint nvarchar(1000), RiskLevel varchar(20) NOT NULL, Status varchar(20) NOT NULL, RequiresApproval bit NOT NULL DEFAULT 0);
CREATE TABLE Permission(PermissionID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), PermissionName nvarchar(200) NOT NULL UNIQUE, ResourceType varchar(60) NOT NULL, Action varchar(60) NOT NULL, RiskLevel varchar(20) NOT NULL);
CREATE TABLE Agent(AgentID uniqueidentifier PRIMARY KEY, CompanyID uniqueidentifier NOT NULL REFERENCES Company(CompanyID), DepartmentID uniqueidentifier NOT NULL REFERENCES Department(DepartmentID), PositionID uniqueidentifier NULL REFERENCES Position(PositionID), AgentName nvarchar(200) NOT NULL, AgentType varchar(30) NOT NULL, Grade varchar(20) NOT NULL, ManagerAgentID uniqueidentifier NULL, DirectorAgentID uniqueidentifier NULL, JobDescription nvarchar(max) NOT NULL, ResponsibilitiesJson nvarchar(max), SecurityRoleID uniqueidentifier NULL, ApprovalAuthorityID uniqueidentifier NULL, Model nvarchar(100), ModelVersion nvarchar(50), PromptVersion nvarchar(50), AutonomyLevel tinyint NOT NULL, RiskLevel varchar(20) NOT NULL, CostLimitMonthly decimal(18,2) NOT NULL DEFAULT 0, TokenLimitDaily bigint NOT NULL DEFAULT 0, ConcurrentTaskLimit int NOT NULL DEFAULT 1, CurrentWorkload decimal(5,2) NOT NULL DEFAULT 0, CreatedDate datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), LastEvaluationDate datetime2 NULL, ExpiryDate datetime2 NULL, Status varchar(30) NOT NULL, CreatedBy nvarchar(200) NOT NULL, ModifiedDate datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), ModifiedBy nvarchar(200) NOT NULL, FOREIGN KEY(ManagerAgentID) REFERENCES Agent(AgentID), CHECK(AutonomyLevel BETWEEN 0 AND 5), CHECK(Status IN ('Requested','Provisioning','Training','Testing','PendingApproval','Active','Suspended','Inactive','Retired')));
CREATE TABLE AgentSkill(AgentID uniqueidentifier NOT NULL REFERENCES Agent(AgentID), SkillID uniqueidentifier NOT NULL REFERENCES Skill(SkillID), Proficiency tinyint NOT NULL, Status varchar(20) NOT NULL, PRIMARY KEY(AgentID,SkillID));
CREATE TABLE AgentTool(AgentID uniqueidentifier NOT NULL REFERENCES Agent(AgentID), ToolID uniqueidentifier NOT NULL REFERENCES Tool(ToolID), ValidFrom datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), ValidTo datetime2 NULL, Status varchar(20) NOT NULL, PRIMARY KEY(AgentID,ToolID));
CREATE TABLE AgentPermission(AgentID uniqueidentifier NOT NULL REFERENCES Agent(AgentID), PermissionID uniqueidentifier NOT NULL REFERENCES Permission(PermissionID), Environment varchar(20) NOT NULL, ValidFrom datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), ValidTo datetime2 NULL, Status varchar(20) NOT NULL, PRIMARY KEY(AgentID,PermissionID,Environment));
CREATE TABLE Requirement(RequirementID uniqueidentifier PRIMARY KEY, Title nvarchar(200) NOT NULL, Description nvarchar(max) NOT NULL, RequestedBy nvarchar(200) NOT NULL, Priority varchar(20) NOT NULL, RiskLevel varchar(20) NOT NULL, Status varchar(30) NOT NULL, CreatedAtUtc datetime2 NOT NULL, CreatedBy nvarchar(200) NOT NULL, ModifiedAtUtc datetime2 NOT NULL, ModifiedBy nvarchar(200) NOT NULL);
CREATE TABLE RequirementSkill(RequirementID uniqueidentifier NOT NULL REFERENCES Requirement(RequirementID), SkillID uniqueidentifier NOT NULL REFERENCES Skill(SkillID), Priority varchar(20), PRIMARY KEY(RequirementID,SkillID));
CREATE TABLE Project(ProjectID uniqueidentifier PRIMARY KEY, RequirementID uniqueidentifier NULL REFERENCES Requirement(RequirementID), ProjectName nvarchar(250) NOT NULL, Objective nvarchar(max) NOT NULL, BusinessOwner nvarchar(200) NOT NULL, BudgetAmount decimal(18,2) NOT NULL DEFAULT 0, Status varchar(30) NOT NULL, CreatedAtUtc datetime2 NOT NULL, CreatedBy nvarchar(200) NOT NULL, ModifiedAtUtc datetime2 NOT NULL, ModifiedBy nvarchar(200) NOT NULL);
CREATE TABLE ProjectAgent(ProjectID uniqueidentifier NOT NULL REFERENCES Project(ProjectID), AgentID uniqueidentifier NOT NULL REFERENCES Agent(AgentID), ProjectRole nvarchar(100) NOT NULL, AssignedAtUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), EndAtUtc datetime2 NULL, PRIMARY KEY(ProjectID,AgentID));
CREATE TABLE Task(TaskID uniqueidentifier PRIMARY KEY, ProjectID uniqueidentifier NOT NULL REFERENCES Project(ProjectID), ParentTaskID uniqueidentifier NULL REFERENCES Task(TaskID), Description nvarchar(max) NOT NULL, Priority varchar(20) NOT NULL, AssignedAgentID uniqueidentifier NULL REFERENCES Agent(AgentID), RiskLevel varchar(20) NOT NULL, BudgetLimit decimal(18,2) NOT NULL DEFAULT 0, TokenLimit bigint NOT NULL DEFAULT 0, Status varchar(30) NOT NULL, ApprovalRequired bit NOT NULL DEFAULT 0, CreatedAtUtc datetime2 NOT NULL, CreatedBy nvarchar(200) NOT NULL, ModifiedAtUtc datetime2 NOT NULL, ModifiedBy nvarchar(200) NOT NULL);
CREATE TABLE TaskDependency(TaskID uniqueidentifier NOT NULL REFERENCES Task(TaskID), DependsOnTaskID uniqueidentifier NOT NULL REFERENCES Task(TaskID), DependencyType varchar(30) NOT NULL DEFAULT 'FinishStart', PRIMARY KEY(TaskID,DependsOnTaskID));
CREATE TABLE TaskAssignment(TaskAssignmentID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), TaskID uniqueidentifier NOT NULL REFERENCES Task(TaskID), AgentID uniqueidentifier NOT NULL REFERENCES Agent(AgentID), AssignedAtUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), ReleasedAtUtc datetime2 NULL, Status varchar(20) NOT NULL);
CREATE TABLE AgentMessage(MessageID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), CorrelationID uniqueidentifier NOT NULL, SenderAgentID uniqueidentifier NOT NULL REFERENCES Agent(AgentID), ReceiverAgentID uniqueidentifier NOT NULL REFERENCES Agent(AgentID), ProjectID uniqueidentifier NULL REFERENCES Project(ProjectID), TaskID uniqueidentifier NULL REFERENCES Task(TaskID), MessageType varchar(30) NOT NULL, Priority varchar(20) NOT NULL, Payload nvarchar(max) NOT NULL, CreatedAtUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Workflow(WorkflowID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), WorkflowName nvarchar(200) NOT NULL, Version varchar(30) NOT NULL, DefinitionJson nvarchar(max) NOT NULL, Status varchar(20) NOT NULL);
CREATE TABLE WorkflowExecution(WorkflowExecutionID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), WorkflowID uniqueidentifier NOT NULL REFERENCES Workflow(WorkflowID), CorrelationID uniqueidentifier NOT NULL, Status varchar(30) NOT NULL, StartedAtUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), CompletedAtUtc datetime2 NULL, StateJson nvarchar(max));
CREATE TABLE Approval(ApprovalID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), ProjectID uniqueidentifier NULL REFERENCES Project(ProjectID), TaskID uniqueidentifier NULL REFERENCES Task(TaskID), ApprovalType varchar(50) NOT NULL, RequestedBy nvarchar(200) NOT NULL, Approver nvarchar(200) NOT NULL, Status varchar(20) NOT NULL, ArtifactHash varchar(100) NULL, RequestedAtUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME(), DecidedAtUtc datetime2 NULL);
CREATE TABLE Risk(RiskID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), ProjectID uniqueidentifier NOT NULL REFERENCES Project(ProjectID), Title nvarchar(250) NOT NULL, RiskLevel varchar(20) NOT NULL, Status varchar(20) NOT NULL, Owner nvarchar(200), Mitigation nvarchar(max));
CREATE TABLE Issue(IssueID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), ProjectID uniqueidentifier NOT NULL REFERENCES Project(ProjectID), Title nvarchar(250) NOT NULL, Severity varchar(20) NOT NULL, Status varchar(20) NOT NULL, Owner nvarchar(200));
CREATE TABLE Decision(DecisionID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), ProjectID uniqueidentifier NOT NULL REFERENCES Project(ProjectID), DecisionText nvarchar(max) NOT NULL, DecidedBy nvarchar(200) NOT NULL, Evidence nvarchar(max), CreatedAtUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE Deliverable(DeliverableID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), ProjectID uniqueidentifier NOT NULL REFERENCES Project(ProjectID), TaskID uniqueidentifier NULL REFERENCES Task(TaskID), Name nvarchar(250) NOT NULL, ArtifactUri nvarchar(1000), ArtifactHash varchar(100), Status varchar(20) NOT NULL);
CREATE TABLE Evaluation(EvaluationID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), AgentID uniqueidentifier NOT NULL REFERENCES Agent(AgentID), TaskID uniqueidentifier NULL REFERENCES Task(TaskID), EvaluationType varchar(60) NOT NULL, Score decimal(9,4) NOT NULL, Passed bit NOT NULL, Evidence nvarchar(max), CreatedAtUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE AgentPerformance(PerformanceID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), AgentID uniqueidentifier NOT NULL REFERENCES Agent(AgentID), PeriodStart date NOT NULL, PeriodEnd date NOT NULL, CompletionRate decimal(9,4), ReworkRate decimal(9,4), ErrorRate decimal(9,4), CostPerTask decimal(18,4));
CREATE TABLE Budget(BudgetID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), ProjectID uniqueidentifier NULL REFERENCES Project(ProjectID), DepartmentID uniqueidentifier NULL REFERENCES Department(DepartmentID), Amount decimal(18,2) NOT NULL, ConsumedAmount decimal(18,2) NOT NULL DEFAULT 0, Currency char(3) NOT NULL DEFAULT 'AED', Status varchar(20) NOT NULL);
CREATE TABLE AgentCost(AgentCostID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), AgentID uniqueidentifier NOT NULL REFERENCES Agent(AgentID), TaskID uniqueidentifier NULL REFERENCES Task(TaskID), CostType varchar(40) NOT NULL, Quantity decimal(18,6) NOT NULL, UnitCost decimal(18,8) NOT NULL, TotalCost AS (Quantity*UnitCost) PERSISTED, Currency char(3) NOT NULL DEFAULT 'AED', CreatedAtUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE AuditLog(AuditLogID bigint IDENTITY(1,1) PRIMARY KEY, CorrelationID uniqueidentifier NOT NULL, ActorType varchar(30) NOT NULL, ActorID nvarchar(200) NOT NULL, Action nvarchar(200) NOT NULL, ResourceType varchar(100) NOT NULL, ResourceID nvarchar(200), Outcome varchar(30) NOT NULL, EvidenceHash varchar(100), Details nvarchar(max), CreatedAtUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE KnowledgeSource(KnowledgeSourceID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), SourceName nvarchar(200) NOT NULL, SourceType varchar(50) NOT NULL, Uri nvarchar(1000), Classification varchar(30) NOT NULL, Owner nvarchar(200) NOT NULL, Status varchar(20) NOT NULL);
CREATE TABLE AgentKnowledgeAccess(AgentID uniqueidentifier NOT NULL REFERENCES Agent(AgentID), KnowledgeSourceID uniqueidentifier NOT NULL REFERENCES KnowledgeSource(KnowledgeSourceID), AccessLevel varchar(30) NOT NULL, ValidTo datetime2 NULL, PRIMARY KEY(AgentID,KnowledgeSourceID));
CREATE TABLE Policy(PolicyID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), PolicyName nvarchar(200) NOT NULL, Version varchar(30) NOT NULL, RulesJson nvarchar(max) NOT NULL, RiskLevel varchar(20) NOT NULL, Status varchar(20) NOT NULL);
CREATE TABLE PolicyViolation(PolicyViolationID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), PolicyID uniqueidentifier NOT NULL REFERENCES Policy(PolicyID), AgentID uniqueidentifier NULL REFERENCES Agent(AgentID), TaskID uniqueidentifier NULL REFERENCES Task(TaskID), Severity varchar(20) NOT NULL, Details nvarchar(max) NOT NULL, Status varchar(20) NOT NULL, DetectedAtUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
CREATE TABLE SecurityIncident(SecurityIncidentID uniqueidentifier PRIMARY KEY DEFAULT NEWID(), AgentID uniqueidentifier NULL REFERENCES Agent(AgentID), ProjectID uniqueidentifier NULL REFERENCES Project(ProjectID), Severity varchar(20) NOT NULL, Category varchar(80) NOT NULL, Description nvarchar(max) NOT NULL, Status varchar(20) NOT NULL, DetectedAtUtc datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
GO
CREATE INDEX IX_Agent_Department_Status ON Agent(DepartmentID,Status);
CREATE INDEX IX_Agent_Manager ON Agent(ManagerAgentID);
CREATE INDEX IX_Task_Project_Status ON Task(ProjectID,Status,Priority);
CREATE INDEX IX_Audit_Correlation ON AuditLog(CorrelationID,CreatedAtUtc);
CREATE INDEX IX_Message_Correlation ON AgentMessage(CorrelationID,CreatedAtUtc);
CREATE INDEX IX_AgentCost_Task ON AgentCost(TaskID,CreatedAtUtc);
GO
